import datasets, pandas as pd, numpy as np
from scipy.optimize import curve_fit

ds = datasets.load_from_disk('/app/data')
df = ds.to_pandas()

# Fit per group: brier_score = C + A * flops^(-alpha)
def chinchilla(x, C, A, alpha):
    return C + A * x**(-alpha)

params = {}
for group in df['group'].unique():
    sub = df[df['group']==group].sort_values('flops')
    x = sub['flops'].values
    y = sub['brier_score'].values
    try:
        p, _ = curve_fit(chinchilla, x, y, p0=[-0.5, 0.1, 0.3], maxfev=20000,
                        bounds=([-2, -10, 0], [0, 10, 2]))
        r = np.std(y - chinchilla(x, *p))
        params[group] = {'C': p[0], 'A': p[1], 'alpha': p[2], 'resid': r}
        print(f'{group}: C={p[0]:.6f} A={p[1]:.6f} alpha={p[2]:.6f} resid={r:.4f}')
    except Exception as e:
        print(f'{group}: FAILED {e}')
